def dedupe_and_backfill(apps, schema_editor):
    """
    Prepare the existing 1338 seeded rows for the open catalogue.

    Two jobs, in this order, because the second would fail without the first:

    1. Collapse duplicate `deezer_id`s. The old seeding paths keyed on
       (title, artist) and could import the same Deezer track twice under
       slightly different spellings, so the new uniqueness constraint would be
       rejected outright. Foreign keys are repointed at the survivor rather
       than cascaded away, so no duel history or playlist entry is lost.
    2. Fill `norm_title` / `norm_artist`. These are maintained by Track.save(),
       which historical models do not run, so the normaliser is called here
       directly.
    """
    from game.services.matching import normalize_artist, normalize_title

    Track = apps.get_model('game', 'Track')
    PlaylistTrack = apps.get_model('game', 'PlaylistTrack')
    DuelRound = apps.get_model('game', 'DuelRound')

    # ── 1. Dedupe ────────────────────────────────────────────────────────────
    seen = {}
    duplicates = []
    for track in Track.objects.exclude(deezer_id=None).order_by('created_at', 'id'):
        keeper = seen.get(track.deezer_id)
        if keeper is None:
            seen[track.deezer_id] = track.id
        else:
            duplicates.append((track.id, keeper))

    for loser_id, keeper_id in duplicates:
        # A playlist may already hold the keeper; that row would violate the
        # (playlist, track) uniqueness, so drop the loser's entry instead.
        for entry in PlaylistTrack.objects.filter(track_id=loser_id):
            clash = PlaylistTrack.objects.filter(
                playlist_id=entry.playlist_id, track_id=keeper_id,
            ).exists()
            if clash:
                entry.delete()
            else:
                entry.track_id = keeper_id
                entry.save(update_fields=['track'])
        DuelRound.objects.filter(track_id=loser_id).update(track_id=keeper_id)

    if duplicates:
        Track.objects.filter(id__in=[loser for loser, _ in duplicates]).delete()

    # ── 2. Backfill the identity columns ─────────────────────────────────────
    batch = []
    for track in Track.objects.all().only('id', 'title', 'artist').iterator(chunk_size=500):
        track.norm_title = normalize_title(track.title)
        track.norm_artist = normalize_artist(track.artist)
        batch.append(track)
        if len(batch) >= 500:
            Track.objects.bulk_update(batch, ['norm_title', 'norm_artist'])
            batch = []
    if batch:
        Track.objects.bulk_update(batch, ['norm_title', 'norm_artist'])


